    onClose();
  };
  return ov;
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["kernel_check"];
  if (!bundle) return;
  var parse = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckParse;
  var compare = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckCompare;
  var age = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckAge;
  var render = bundle._eliViewFns && bundle._eliViewFns.renderKernelUpdate;
  var renderDone = bundle._eliViewFns && bundle._eliViewFns.renderKernelUpdated;
  if (!parse || !compare || !age || !render || !renderDone) {
    eli.log.event("tool", "kernel_check_init_missing_fns", {
      parse: !!parse, compare: !!compare, age: !!age,
      render: !!render, renderDone: !!renderDone,
    });
    return;
  }

  var MARKER_URL = "https://cdn.jsdelivr.net/gh/apndrewn/eli-data@main/kernel-latest.json";
  // Written when the how-to-update screen is shown; read back once the
  // install is actually on that version. Nobody who never saw the prompt
  // gets a change log for an update they didn't make.
  var PENDING_KEY = "kernel_check_pending";
  // The dashboard paints first; an overlay racing it reads as a crash.
  var SHOW_DELAY_MS = 2500;
  var _open = false;
  // Session-only. A persisted "don't ask again" on something you actually
  // need to do just hides the prompt while leaving the install stale.
  var _closedThisSession = false;

  // jsdelivr serves a cold 404 for up to a minute after a push and caches
  // aggressively afterwards. Same fallback eli-admin uses for overrides.
  function _rawFallbackUrl(u) {
    var m = /^https:\/\/cdn\.jsdelivr\.net\/gh\/([^/]+)\/([^/@]+)@([^/]+)\/(.+)$/.exec(u || "");
    return m ? ("https://raw.githubusercontent.com/" + m[1] + "/" + m[2] + "/" + m[3] + "/" + m[4]) : null;
  }

  function _fetchMarker() {
    if (typeof navigator !== "undefined" && navigator.onLine === false) {
      return Promise.resolve(null);
    }
    if (typeof fetch === "undefined") return Promise.resolve(null);
    function _try(u, isFallback) {
      var busted = u + (u.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
      return fetch(busted, { cache: "no-store" }).then(function (res) {
        if (!res.ok) {
          if (!isFallback) {
            var raw = _rawFallbackUrl(u);
            if (raw) return _try(raw, true);
          }
          throw new Error("marker fetch failed: " + res.status);
        }
        return res.json();
      });
    }
    return _try(MARKER_URL, false).catch(function (e) {
      // Not silent: a marker we can never read means this tool is dead
      // weight, and that should be discoverable rather than invisible.
      eli.log.event("tool", "kernel_check_fetch_failed", { msg: e && e.message });
      return null;
    });
  }

  // Remember what we prompted for, so the change log can be shown after the
  // update instead of before it.
  function _setPending(latest) {
    return eli.storage.put("config", {
      key: PENDING_KEY, value: { version: latest.version, notes: latest.notes || "" },
    }).catch(function (e) {
      // Only costs the post-update screen, but a silent miss would look
      // like the notes were never published.
      eli.log.event("tool", "kernel_check_pending_write_failed", { msg: e && e.message });
    });
  }

  function _show(latest, verdict) {
    if (_open) return;
    _open = true;
    _setPending(latest);
    render({
      latest: latest,
      ageDays: age(latest.builtAt, Date.now()),
      // There is no "I've updated" — updating replaces the snippet, so a
      // reload is what dismisses this. Closing only quiets the session.
      onLater: function () { _open = false; _closedThisSession = true; },
    });
    eli.log.event("tool", "kernel_check_notice_shown", { reason: verdict.reason });
  }

  // Once you're on the version you were prompted for, say what it brought.
  function _showUpdatedIfPending(currentVersion) {
    return eli.storage.get("config", PENDING_KEY).then(function (row) {
      var p = row && row.value;
      if (!p || p.version !== currentVersion) return;
      return eli.storage.delete("config", PENDING_KEY).catch(function () {})
        .then(function () {
          if (_open) return;
          _open = true;
          setTimeout(function () {
            renderDone({
              version: currentVersion,
              notes: p.notes || "",
              onClose: function () { _open = false; },
            });
          }, SHOW_DELAY_MS);
        });
    }).catch(function () { /* nothing pending we can act on */ });
  }

  // force: the tile opens the instructions on demand.
  function _check(force) {
    if (_open) return Promise.resolve();
    return _fetchMarker().then(function (raw) {
      var latest = parse(raw);
      if (!latest) {
        if (force) showToast("No ELI OS version has been published yet.", "info");
        return;
      }
      var verdict = compare(eli.kernelVersion, latest);
      if (verdict.state !== "behind") {
        if (force) {
          showToast(verdict.state === "current"
            ? "ELI OS is up to date (" + latest.version + ")."
            : "ELI OS " + verdict.state + " — " + verdict.reason, "ok");
        }
        // Caught up since we last prompted — that's the moment for the notes.
        if (verdict.state === "current") return _showUpdatedIfPending(latest.version);
        return;
      }
      if (force) return _show(latest, verdict);
      if (_closedThisSession) return;
      setTimeout(function () { _show(latest, verdict); }, SHOW_DELAY_MS);
    });
  }

  // Fetched once per session — the fleet view asks for it per render.
  var _latestCache = null;

  eli.register({
    tile: { app_kernel_check: function () { _check(true); } },
    kernel_check: {
      open: function () { _check(true); },
      check: function () { return _check(false); },
      // For admin_fleet's kernel view. Exposing the marker and the
      // comparison rather than letting callers reimplement it is what stops
      // the fleet table and the user's own notice from disagreeing.
      latest: function (force) {
        if (_latestCache && !force) return Promise.resolve(_latestCache);
        return _fetchMarker().then(function (raw) {
          _latestCache = parse(raw);
          return _latestCache;
        });
      },
      verdict: function (version, latest) { return compare(version, latest); },
    },
  });

  _check(false);
}

jsonTools.css:
/* tools/kernel_check/style.css
   Keyframes only — everything else is inlined on the element for
   guaranteed paint (taskpane_v3.css is the only sheet the runtime loads). */

._eli3_kc_overlay { animation: _eli3_kc_fade 160ms ease-out; }
._eli3_kc_card { animation: _eli3_kc_rise 220ms cubic-bezier(.2,.8,.3,1); }

@keyframes _eli3_kc_fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes _eli3_kc_rise {
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to   { opacity: 1; transform: none; }
}
